export default function Table(){

    let tableInfo = {
        headers : [
            "test1",
            "test2",
            "test3",
        ]
    }

    const tableHeaders = [];
    const tableContents = [];

    for(let header in tableInfo.headers){
        tableHeaders.push(<span className='flex-auto border-r' >{header}</span>);
    }

    return(
        <div className="table border w-2/5">
            <div className="tableHeaders flex flex-row bg-black text-white text-center">{tableHeaders}</div>
        </div>
    );
}
